-- 매시 정각 약 13초 정지 진단(11-25 ①②A 모두 HH:00:01~14초). 정각 약 1분 전에 sql.sh로 시작, 4초마다 12번
SELECT NOW(3) t,COUNT(*) busy,MAX(time) maxt,(SELECT COUNT(*) FROM information_schema.innodb_trx) trx,(SELECT COUNT(*) FROM performance_schema.data_lock_waits) lw,LEFT(GROUP_CONCAT(CONCAT(time,'s ',state,' ',LEFT(info,50)) ORDER BY time DESC SEPARATOR ' | '),300) top FROM information_schema.processlist WHERE command NOT IN ('Sleep','Daemon') AND id<>CONNECTION_ID();DO SLEEP(4);
